#ifndef RINGBUF_H
#define RINGBUF_H

#include <stddef.h>
#include <stdint.h>

/* Fixed-capacity FIFO ring buffer of bytes. Not thread-safe. */
typedef struct ringbuf ringbuf_t;

/* Create a buffer holding up to `capacity` bytes (capacity > 0).
 * Returns NULL on invalid capacity or allocation failure. */
ringbuf_t *rb_create(size_t capacity);

/* Free the buffer. Accepts NULL. */
void rb_destroy(ringbuf_t *rb);

/* Append up to `len` bytes from `data`. Writes as many bytes as fit and
 * returns the number actually written (0 if full or arguments are NULL). */
size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len);

/* Remove up to `len` bytes into `out`, oldest first. Returns the number
 * actually read (0 if empty or arguments are NULL). */
size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len);

/* Copy up to `len` oldest bytes into `out` without removing them. */
size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len);

/* Number of bytes currently stored. */
size_t rb_size(const ringbuf_t *rb);

/* Total capacity given at creation. */
size_t rb_capacity(const ringbuf_t *rb);

/* Discard all content. */
void rb_clear(ringbuf_t *rb);

#endif

input.content:
#include "ringbuf.h"
#include <stdlib.h>

struct ringbuf {
    uint8_t *buf;
    size_t capacity;
    size_t head;   /* write index */
    size_t tail;   /* read index */
    size_t count;  /* bytes currently stored */
};

ringbuf_t *rb_create(size_t capacity)
{
    if (capacity == 0)
        return NULL;

    ringbuf_t *rb = malloc(sizeof(ringbuf_t));
    if (!rb)
        return NULL;

    rb->buf = calloc(capacity, sizeof(uint8_t));
    if (!rb->buf) {
        free(rb);
        return NULL;
    }

    rb->capacity = capacity;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
    return rb;
}

void rb_destroy(ringbuf_t *rb)
{
    if (!rb)
        return;
    free(rb->buf);
    free(rb);
}

size_t rb_write(ringbuf_t *rb, const uint8_t *data, size_t len)
{
    if (!rb || !data || len == 0)
        return 0;

    size_t free_space = rb->capacity - rb->count;
    size_t to_write = len < free_space ? len : free_space;

    for (size_t i = 0; i < to_write; i++) {
        rb->buf[rb->head] = data[i];
        rb->head = (rb->head + 1) % rb->capacity;
    }

    rb->count += to_write;
    return to_write;
}

size_t rb_read(ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->count == 0)
        return 0;

    size_t to_read = len < rb->count ? len : rb->count;

    for (size_t i = 0; i < to_read; i++) {
        out[i] = rb->buf[rb->tail];
        rb->tail = (rb->tail + 1) % rb->capacity;
    }

    rb->count -= to_read;
    return to_read;
}

size_t rb_peek(const ringbuf_t *rb, uint8_t *out, size_t len)
{
    if (!rb || !out || len == 0 || rb->count == 0)
        return 0;

    size_t to_peek = len < rb->count ? len : rb->count;
    size_t idx = rb->tail;

    for (size_t i = 0; i < to_peek; i++) {
        out[i] = rb->buf[idx];
        idx = (idx + 1) % rb->capacity;
    }

    return to_peek;
}

size_t rb_size(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->count;
}

size_t rb_capacity(const ringbuf_t *rb)
{
    if (!rb)
        return 0;
    return rb->capacity;
}

void rb_clear(ringbuf_t *rb)
{
    if (!rb)
        return;
    rb->head = 0;
    rb->tail = 0;
    rb->count = 0;
}

