#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

int main(void)
{
    int pass = 1;

    /* Test NULL safety */
    if (rb_create(0) != NULL) { pass = 0; }
    if (rb_size(NULL) != 0) { pass = 0; }
    rb_destroy(NULL); /* should not crash */

    ringbuf_t *rb = rb_create(4);
    if (!rb) { printf("FAIL: create\n"); return 1; }
    if (rb_capacity(rb) != 4) { pass = 0; }
    if (rb_size(rb) != 0) { pass = 0; }

    /* Write and read */
    uint8_t wdata[] = {1, 2, 3, 4, 5};
    size_t n = rb_write(rb, wdata, 5);
    if (n != 4) { pass = 0; printf("write returned %zu\n", n); }
    if (rb_size(rb) != 4) { pass = 0; }

    /* Peek */
    uint8_t peek[4];
    if (rb_peek(rb, peek, 4) != 4) { pass = 0; }
    if (peek[0] != 1 || peek[3] != 4) { pass = 0; }

    /* Read */
    uint8_t rdata[4];
    if (rb_read(rb, rdata, 4) != 4) { pass = 0; }
    if (rdata[0] != 1 || rdata[3] != 4) { pass = 0; }
    if (rb_size(rb) != 0) { pass = 0; }

    /* Wrap-around test */
    rb_write(rb, wdata, 2); /* fills 1,2 at head=0,tail=0 -> head=2,tail=0 */
    rb_read(rb, rdata, 1);  /* reads 1, tail=1 */
    uint8_t w2[] = {10, 20, 30, 40};
    n = rb_write(rb, w2, 4);
    if (n != 3) { pass = 0; printf("wrap write returned %zu\n", n); }
    /* buffer now: [_, 2, 10, 20] tail=1 head=0 */

    uint8_t rbuf[4];
    size_t rn = rb_read(rb, rbuf, 4);
    if (rn != 3 || rbuf[0] != 2 || rbuf[1] != 10 || rbuf[2] != 20) {
        pass = 0; printf("wrap read failed\n");
    }

    /* Clear */
    rb_write(rb, wdata, 4);
    rb_clear(rb);
    if (rb_size(rb) != 0) { pass = 0; }

    rb_destroy(rb);

    if (pass)
        printf("ALL PASSED\n");
    else
        printf("FAILURES DETECTED\n");

    return pass ? 0 : 1;
}
EOF
